'use strict';

// MODULES //

var isAsci = require( '@stdlib/assert/is-ascii' );
var format = require( '@stdlib/string/format' );
var isValidRowCol = require( './utils/is-valid-row-col.js' );

/**
* Add string.
*
* @private
* @name addString
* @param {number} row - row number
* @param {number} col - col number
* @param {string} value - String or Array of grapheme cluster
* @param {boolean} overwrite - overwrite
* @param {string} color - color code
* @throws {TypeError} must be valid number of arguments
* @returns {void}
*/
function addString() {
	var overwrite;
	var color;
	var cond1;
	var cond2;
	var value;
	var chr;
	var r;
	var c;
	var i;

	r = NaN;
	c = NaN;
	value = '';
	overwrite = false;
	color = this.foregroundColor;
	if ( arguments.length >= 3 ) {
		r = arguments[ 0 ];
		c = arguments[ 1 ];
		value = arguments[ 2 ];
	}
	else {
		throw new TypeError( format( 'invalid arguments. expected number of arguments must be greater then or equal to 3: `%s`: `%s`.', 'args number', arguments.length ) );
	}
	if ( arguments.length >= 4 ) {
		overwrite = arguments[ 3 ];
	}
	if ( arguments.length === 5 ) {
		color = arguments[ 4 ];
	}

	for ( i = 0; i < value.length; i++ ) {
		chr = value[ i ];
		cond1 = isValidRowCol( r, c, this._height, this._width );
		cond2 = ( overwrite || this._glyphMatrix[ r ][ c ] === this._glyph );
		if ( isAsci( chr ) && cond1 && cond2 ) {
			this.setGlyph( r, c, 'asci' + chr.charCodeAt( 0 ), overwrite );
		}
		if ( cond1 ) {
			this.setForegroundColor( r, c, color, overwrite );
		}
		c+=1;
	}
}

module.exports = addString;
